// LIFE4和Condition真实死亡cause共享唯一字段遍历；无自由JSON或legacy时间推断。
#pragma once
#include "family_life_exact_types.hpp"
#include <type_traits>
#include "resident/checkpoint/codec_visitor.hpp"
namespace hanmo::resident::family_life4_codec {
template<class C>Status moment(C& c,WorldMoment& m){if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)(void)0;EncodedWorldMoment e;if(!c.reading()){auto x=encode_world_moment(m);if(!x.ok)return {false,{},x.error};e=std::move(x.value);}c.field("half_day_tick",e.half_day_tick);c.object("sub_half_day",[&](C& v){v.field("numerator",e.sub_half_day.numerator);return v.field("denominator",e.sub_half_day.denominator);});if(c.reading()&&c.status().ok){auto x=decode_world_moment(e);if(!x.ok)return {false,{},x.error};m=std::move(x.value);}return c.status();}
template<class C>Status cause(C& c,LifeCauseRef4& value){StableId kind=value.index()==0?"military_casualty":value.index()==1?"natural_age":"environmental_sea";c.field("kind",kind);if(kind!="military_casualty"&&kind!="natural_age"&&kind!="environmental_sea")return c.reject("InvalidLifeCause4");if(c.reading())value=kind=="military_casualty"?LifeCauseRef4{MilitaryDeathCause4{}}:kind=="natural_age"?LifeCauseRef4{NaturalAgeDeathCause4{}}:LifeCauseRef4{EnvironmentalSeaDeathCause4{}};
    if(auto* m=std::get_if<MilitaryDeathCause4>(&value)){c.field("casualty_fact_id",m->casualty_fact_id);c.field("battle_id",m->battle_id);c.field("actor_id",m->actor_id);c.object("occurrence_at",[&](C& v){return moment(v,m->occurrence_at);});if(m->casualty_fact_id.empty()||m->battle_id.empty()||m->actor_id.empty())return c.reject("InvalidMilitaryDeathCause4");}
    else if(auto* a=std::get_if<NaturalAgeDeathCause4>(&value)){c.field("age_check_fact_id",a->age_check_fact_id);if(a->age_check_fact_id.empty())return c.reject("InvalidNaturalAgeDeathCause4");}
    else {auto& s=std::get<EnvironmentalSeaDeathCause4>(value);c.field("sea_loss_result_id",s.sea_loss_result_id);c.field("actor_id",s.actor_id);c.field("vessel_passenger_binding_ref",s.vessel_passenger_binding_ref);c.object("occurrence_at",[&](C& v){return moment(v,s.occurrence_at);});if(s.sea_loss_result_id.empty()||s.actor_id.empty()||s.vessel_passenger_binding_ref.empty())return c.reject("InvalidEnvironmentalSeaDeathCause4");}return c.status();}
template<class C>Status world(C& c,WorldId& id){StableId text;if(!c.reading()){constexpr char hex[]="0123456789abcdef";for(auto x:id){text.push_back(hex[x>>4]);text.push_back(hex[x&15]);}}c.field("world_id",text);if(text.size()!=32)return c.reject("InvalidFamilyDeathWorldId");if(c.reading())for(std::size_t i=0;i<16;++i){auto digit=[](char x){return x>='0'&&x<='9'?x-'0':x>='a'&&x<='f'?x-'a'+10:-1;};auto a=digit(text[2*i]),b=digit(text[2*i+1]);if(a<0||b<0)return c.reject("InvalidFamilyDeathWorldId");id[i]=std::uint8_t(a*16+b);}return c.status();}
}
